import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.D1JEzK2q.js";const k=JSON.parse('{"title":"Development","description":"","frontmatter":{},"headers":[],"relativePath":"reference/development.md","filePath":"reference/development.md"}'),n={name:"reference/development.md"};function d(o,e,r,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h1><p>Keep development builds separate from a gateway serving active users. Rebuilding a live checkout can leave gateway and MCP code from different revisions and interrupt sessions.</p><h2 id="source-setup" tabindex="-1">Source setup <a class="header-anchor" href="#source-setup" aria-label="Permalink to &quot;Source setup&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/0xMaxMa/claude-gateway.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-gateway</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Node.js 22+ and Bun are required. <code>postinstall</code> installs MCP dependencies through Bun when available. Check <code>claude --version</code> and authenticate under the operating-system account that runs the gateway. Docker/Compose is required only for app-related development, and audio conversion paths may require <code>ffmpeg</code>.</p><p>Start a development gateway deliberately:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>It uses the same default config directory as an installed gateway. To test independently, set <code>GATEWAY_CONFIG</code>, <code>PORT</code>, and distinct agent workspace paths before starting. Do not accidentally start two receivers with the same bot token.</p><h2 id="repository-map" tabindex="-1">Repository map <a class="header-anchor" href="#repository-map" aria-label="Permalink to &quot;Repository map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>What belongs here</th></tr></thead><tbody><tr><td><code>src/agent/</code></td><td>Claude Code process/session handling, skills, memory and background agent jobs</td></tr><tr><td><code>src/orchestration/</code></td><td>Durable conversations, worker scheduling, task events and delivery</td></tr><tr><td><code>src/voice/</code></td><td>STT/TTS adapters, turn handling, transport, diagnostics and replay</td></tr><tr><td><code>src/api/</code></td><td>HTTP/WebSocket routes, authorization, channel webhooks</td></tr><tr><td><code>src/cli/</code></td><td>CLI commands, local runtime control and API clients</td></tr><tr><td><code>src/config/</code></td><td>Loading, defaults, migrations and validation</td></tr><tr><td><code>mcp/</code></td><td>Bun MCP server and tool modules</td></tr><tr><td><code>tests/</code></td><td>Unit, integration and end-to-end tests</td></tr><tr><td><code>website/</code></td><td>Documentation source and its independent build</td></tr><tr><td><code>website/reference/cli.md</code></td><td>Generated CLI reference</td></tr></tbody></table><p>This map describes the orchestration codebase documented by this site. Runtime data belongs under the configured gateway home and agent workspaces, not inside the repository.</p><h2 id="test-the-changed-behavior" tabindex="-1">Test the changed behavior <a class="header-anchor" href="#test-the-changed-behavior" aria-label="Permalink to &quot;Test the changed behavior&quot;">​</a></h2><p>Use the smallest meaningful test set while iterating. These examples invoke Jest directly to avoid npm&#39;s <code>pretest</code> build when a rebuild is not needed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-old-space-size=1536</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node_modules/jest/bin/jest.js</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runInBand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/unit/voice/gemini.test.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>The heap size shown is a conservative starting point for a small shared host, not a guaranteed memory bound: Node child processes, native buffers, the compiler, and other services also consume memory. Run builds and tests sequentially on such hosts and monitor available RAM. If the suite needs more memory, move full validation to an appropriately sized CI runner rather than repeatedly exhausting production RAM.</p><p>The standard project commands are:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:unit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integration</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p><code>npm test</code> and <code>npm run test:unit</code> have pretest hooks that compile TypeScript. Do not run several full suites or compiler processes at once on the same small machine. A full suite should run in an isolated development/CI environment before release.</p><p>For async tests, wait for an observable state or event with a bounded deadline rather than an arbitrary sleep. Test real cancellation and failure paths when changing process supervision; CPU movement alone is not proof that a test passed.</p><h2 id="update-documentation-with-code" tabindex="-1">Update documentation with code <a class="header-anchor" href="#update-documentation-with-code" aria-label="Permalink to &quot;Update documentation with code&quot;">​</a></h2><p>HTTP API changes belong in <a href="./../api/">API reference</a>. Update the relevant channel or feature guide when behavior changes. Regenerate <code>website/reference/cli.md</code> with the repository&#39;s CLI generator when changing CLI command definitions. Keep examples consistent with configuration validation, authorization and route mounts.</p><p>The website is built independently:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DOCS_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/claude-gateway/</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Checks build the static pages and validate internal links, anchors, assets and JSON example syntax. They do not start a gateway, run a model, contact a channel or certify that an example is accepted by an external provider. Review changed pages at desktop and mobile sizes before publishing.</p><h2 id="deploy-the-documentation" tabindex="-1">Deploy the documentation <a class="header-anchor" href="#deploy-the-documentation" aria-label="Permalink to &quot;Deploy the documentation&quot;">​</a></h2><p>The website produces static files in <code>website/.vitepress/dist</code>. GitHub Pages hosts this repository at <code>https://0xmaxma.github.io/claude-gateway/</code>. <code>DOCS_BASE=/claude-gateway/</code> ensures links and assets work under that path. A standalone domain uses <code>/</code> instead.</p><p>The deployment workflow builds and checks on main, uploads the static artifact and deploys it through GitHub Pages. PR builds validate without publishing. The initial site can be served from <code>gh-pages</code> until the docs workflow reaches main; the workflow switches the Pages source to GitHub Actions. No gateway restart or application database is needed to publish documentation.</p><p>See the website&#39;s contributor instructions in <a href="https://github.com/0xMaxMa/claude-gateway/blob/docs/documentation-site/website/README.md" target="_blank" rel="noreferrer">website/README.md</a>.</p>`,28)])])}const u=t(n,[["render",d]]);export{k as __pageData,u as default};
